<?php
namespace App\Services;
use App\Support\MarketingCrudPermissions;use Illuminate\Contracts\Auth\Authenticatable;use Illuminate\Support\Facades\DB;
final class MarketingAssetCrudService {
 public function __construct(private readonly MarketingAssetAuthorization $policy,private readonly MarketingConfirmationTokenService $tokens,private readonly MarketingAssetMutationAudit $audit){}
 public function confirmation(Authenticatable $user,string $action,int $client,int $id,array $payload):array{$permission=match($action){'create'=>MarketingCrudPermissions::ASSET_METADATA_CREATE,'update'=>MarketingCrudPermissions::ASSET_METADATA_UPDATE,'archive'=>MarketingCrudPermissions::ASSET_METADATA_ARCHIVE,default=>null};abort_unless($permission,422,'Action metadata aset tidak valid.');if($id){$row=$this->policy->object($user,$id,$permission);abort_unless((int)$row->client_id===$client,403,'client_id tidak sesuai metadata aset.');}else{$this->policy->assert($user,$client,$permission);} $normalized=$action==='archive'?['reason'=>$payload['reason']??null]:$this->payload($payload);$token=$this->tokens->issue($user,$action,'asset_metadata',$id,$this->hash($client,$normalized));return ['action'=>$action,'module'=>'asset_metadata','record_id'=>$id,'client_id'=>$client,'expires_in'=>300,'confirmation_token'=>$token];}
 public function create(Authenticatable $user,array $data):array{$client=(int)$data['client_id'];$payload=$this->payload($data);$this->policy->assert($user,$client,MarketingCrudPermissions::ASSET_METADATA_CREATE);$this->relations($client,$payload);$this->tokens->consume($user,$data['confirmation_token'],'create','asset_metadata',0,$this->hash($client,$payload));$id=DB::transaction(function()use($user,$client,$payload){$metadata=array_intersect_key($payload,array_flip(['project_id','campaign_id','content_plan_id','name','asset_type','mime_type','description']));$id=DB::table('marketing_asset_metadata')->insertGetId($metadata+['client_id'=>$client,'created_by'=>$user->getAuthIdentifier(),'approval_status'=>'draft','current_version'=>1,'created_at'=>now(),'updated_at'=>now()]);DB::table('marketing_asset_versions')->insert(['asset_metadata_id'=>$id,'version_number'=>1,'label'=>$payload['version_label']??'v1','note'=>$payload['version_note']??null,'created_by'=>$user->getAuthIdentifier(),'created_at'=>now()]);return $id;});$this->audit->record($user,'CREATE',$id,$client,$payload);return $this->read($id);}
 public function update(Authenticatable $user,int $id,array $data):array{$row=$this->active($this->policy->object($user,$id,MarketingCrudPermissions::ASSET_METADATA_UPDATE));abort_unless((int)$data['client_id']===(int)$row->client_id,403,'client_id tidak sesuai metadata aset.');$payload=$this->payload($data);$this->relations((int)$row->client_id,$payload);$this->tokens->consume($user,$data['confirmation_token'],'update','asset_metadata',$id,$this->hash((int)$row->client_id,$payload));DB::transaction(function()use($user,$id,$payload){$metadata=array_intersect_key($payload,array_flip(['project_id','campaign_id','content_plan_id','name','asset_type','mime_type','description']));if($metadata)DB::table('marketing_asset_metadata')->where('id',$id)->update($metadata+['updated_at'=>now()]);if(array_key_exists('version_note',$payload)||array_key_exists('version_label',$payload)){$current=(int)DB::table('marketing_asset_metadata')->where('id',$id)->lockForUpdate()->value('current_version');$next=$current+1;DB::table('marketing_asset_versions')->insert(['asset_metadata_id'=>$id,'version_number'=>$next,'label'=>$payload['version_label']??('v'.$next),'note'=>$payload['version_note']??null,'created_by'=>$user->getAuthIdentifier(),'created_at'=>now()]);DB::table('marketing_asset_metadata')->where('id',$id)->update(['current_version'=>$next,'updated_at'=>now()]);}});$this->audit->record($user,'UPDATE',$id,(int)$row->client_id,$payload);return $this->read($id);}
 public function archive(Authenticatable $user,int $id,array $data):array{$row=$this->active($this->policy->object($user,$id,MarketingCrudPermissions::ASSET_METADATA_ARCHIVE));abort_unless((int)$data['client_id']===(int)$row->client_id,403,'client_id tidak sesuai metadata aset.');$payload=['reason'=>$data['reason']];$this->tokens->consume($user,$data['confirmation_token'],'archive','asset_metadata',$id,$this->hash((int)$row->client_id,$payload));DB::table('marketing_asset_metadata')->where('id',$id)->update(['archived_at'=>now(),'archived_by'=>$user->getAuthIdentifier(),'updated_at'=>now()]);$this->audit->record($user,'ARCHIVE',$id,(int)$row->client_id,$payload);return ['id'=>$id,'client_id'=>(int)$row->client_id,'archived'=>true,'scope'=>'client'];}
 private function payload(array $data):array{return array_intersect_key($data,array_flip(['project_id','campaign_id','content_plan_id','name','asset_type','mime_type','description','version_label','version_note']));}
 private function relations(int $client,array $data):void{if(isset($data['project_id']))abort_unless((int)$data['project_id']===$client,422,'project_id harus menunjuk project/client yang sama.');if(isset($data['campaign_id']))abort_unless(DB::table('marketing_campaigns')->where('id',$data['campaign_id'])->where('client_id',$client)->whereNull('archived_at')->exists(),422,'Campaign tidak tersedia untuk client aset.');if(isset($data['content_plan_id']))abort_unless(DB::table('data_jasa')->where('id',$data['content_plan_id'])->where('produk_client_id',$client)->whereNull('archived_at')->exists(),422,'Content plan tidak tersedia untuk client aset.');}
 private function read(int $id):array{$row=(array)DB::table('marketing_asset_metadata')->where('id',$id)->first(['id','client_id','project_id','campaign_id','content_plan_id','created_by','name','asset_type','mime_type','description','approval_status','current_version','archived_at']);$row['versions']=DB::table('marketing_asset_versions')->where('asset_metadata_id',$id)->orderBy('version_number')->get(['version_number','label','note','created_by','created_at'])->map(fn($v)=>(array)$v)->all();return $row;}
 private function active(object $row):object{abort_if($row->archived_at,409,'Metadata aset sudah diarsipkan.');return $row;}private function hash(int $client,array $payload):string{ksort($payload);return hash('sha256',json_encode(['client_id'=>$client,'payload'=>$payload],JSON_THROW_ON_ERROR));}
}
